  ensureDir(path.dirname(resolved));
  fs.writeFileSync(resolved, content);
  res.json({ ok: true });
});

// ─── Docs context cache (injected into AI system prompt) ────────────────────
let _docsCache = null;
let _docsCacheTime = 0;
const DOCS_CACHE_TTL = 5 * 60 * 1000; // refresh every 5 minutes

function loadDocsContext() {
  const now = Date.now();
  if (_docsCache && (now - _docsCacheTime) < DOCS_CACHE_TTL) return _docsCache;
  try {
    if (!fs.existsSync(DOCS_PATH)) { _docsCache = ''; return ''; }
    const files = fs.readdirSync(DOCS_PATH).filter(f => f.endsWith('.md')).sort();
    const parts = files.map(f => {
      const content = fs.readFileSync(path.join(DOCS_PATH, f), 'utf-8').trim();
      return `### ${f}\n${content}`;
    });
    _docsCache = parts.join('\n\n---\n\n');
    _docsCacheTime = now;
    return _docsCache;
  } catch { return ''; }
}

function buildAiSystemPrompt(clientSystem) {
  const base = clientSystem || 'You are an expert Claude Code assistant helping users write and improve their Claude agents, commands, rules, and CLAUDE.md files. Be concise and practical.';
  const docs = loadDocsContext();
  if (!docs) return base;
  return `${base}

---

## Claude Hub Documentation (your knowledge base — use this to answer questions)

${docs}

---

When a user asks how something works, what to add, or how to use any feature, answer using the documentation above. Be concise and practical.`;
}

// Claude AI chat — uses local `claude` CLI via stdin (no API key required)
const { spawn } = require('child_process');

app.post('/api/ai/chat', (req, res) => {
  res.setTimeout(0); // No timeout — allow complex long-running requests
  const { messages, system } = req.body;
  if (!Array.isArray(messages) || messages.length === 0) {
    return res.status(400).json({ error: 'messages array required' });
  }

  const systemText = buildAiSystemPrompt(system);

  let prompt = systemText + '\n\n';
  for (const msg of messages) {
    if (msg.role === 'user') prompt += `Human: ${msg.content}\n\n`;
    else if (msg.role === 'assistant') prompt += `Assistant: ${msg.content}\n\n`;
  }
  prompt += 'Assistant:';

  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;

  // Use stdin to avoid OS argument length limits; -p without an argument reads from stdin
  const proc = spawn(claudePath, ['-p'], {
    env: childEnv,
  });

  let output = '';
  let errOutput = '';

  proc.stdout.on('data', (data) => { output += data.toString(); });
  proc.stderr.on('data', (data) => { errOutput += data.toString(); });

  proc.on('close', (code) => {
    if (code !== 0) {
      return res.status(500).json({ error: errOutput.trim() || `claude exited with code ${code}` });
    }
    res.json({ content: output.trim() });
  });

  proc.on('error', (err) => {
    res.status(500).json({ error: `Failed to run claude: ${err.message}` });
  });

  // Write prompt via stdin and close
  proc.stdin.write(prompt, 'utf8');
  proc.stdin.end();
});

// Claude AI chat — streaming SSE variant
app.post('/api/ai/stream', (req, res) => {
  res.setTimeout(0);
  const { messages, system } = req.body;
  if (!Array.isArray(messages) || messages.length === 0) {
    return res.status(400).json({ error: 'messages array required' });
  }

  const systemText = buildAiSystemPrompt(system);

  let prompt = systemText + '\n\n';
  for (const msg of messages) {
    if (msg.role === 'user') prompt += `Human: ${msg.content}\n\n`;
    else if (msg.role === 'assistant') prompt += `Assistant: ${msg.content}\n\n`;
  }
  prompt += 'Assistant:';

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.flushHeaders();

  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;
  delete childEnv.CLAUDE_CODE_ENTRYPOINT;
  delete childEnv.CLAUDE_CODE_ENABLE_SDK_FILE_CHECKPOINTING;
  delete childEnv.CLAUDE_AGENT_SDK_VERSION;

  const proc = spawn(claudePath, ['-p'], { env: childEnv });
  let fullOutput = '';
  let errOutput = '';

  proc.stdout.on('data', (data) => {
    const chunk = data.toString();
    fullOutput += chunk;
    res.write(`data: ${JSON.stringify({ type: 'chunk', content: chunk })}\n\n`);
  });

  proc.stderr.on('data', (data) => { errOutput += data.toString(); });

  let responded = false;
  const endStream = (eventData) => {
    if (responded) return;
    responded = true;
    res.write(`data: ${JSON.stringify(eventData)}\n\n`);
    res.end();
  };

  proc.on('close', (code, signal) => {
    if (code !== 0 || signal) {
      const errMsg = errOutput.trim() || 'Claude process failed';
      endStream({ type: 'error', error: errMsg });
    } else {
      endStream({ type: 'done', content: fullOutput.trim() });
    }
  });

  proc.on('error', (err) => {
    endStream({ type: 'error', error: err.message });
  });

  proc.stdin.write(prompt, 'utf8');
  proc.stdin.end();

  // Kill child process if client disconnects before it finishes
  const socket = req.socket;
  if (socket) {
    socket.on('close', () => {
      if (!responded) { try { proc.kill(); } catch {} }
    });
  }
});

