// Topological sort helper
function topoSort(nodes, edges) {
  const inDegree = {};
  const adj = {};
  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
  for (const e of edges) {
    adj[e.source].push(e.target);
    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
  }
  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
  const order = [];
  while (queue.length) {
    const id = queue.shift();
    order.push(id);
    for (const next of adj[id]) {
      inDegree[next]--;
      if (inDegree[next] === 0) queue.push(next);
    }
  }
  return order;
}

function runClaudeSync(prompt, timeoutMs = 120000) {
  return new Promise((resolve, reject) => {
    const claudePath = process.env.CLAUDE_PATH || 'claude';
    const childEnv = { ...process.env, HOME: os.homedir() };
    delete childEnv.CLAUDECODE;
    const proc = spawn(claudePath, ['-p'], { env: childEnv });
    let out = '', err = '';
    let killed = false;

    const timer = setTimeout(() => {
      killed = true;
      proc.kill('SIGTERM');
      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
    }, timeoutMs);

    proc.stdout.on('data', d => { out += d.toString(); });
    proc.stderr.on('data', d => { err += d.toString(); });
    proc.on('close', code => {
      clearTimeout(timer);
      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
      else resolve(out.trim());
    });
    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
    proc.stdin.write(prompt, 'utf8');
    proc.stdin.end();
  });
}

app.post('/api/orchestrations/run', async (req, res) => {
  res.setTimeout(0);
  const { nodes, edges, task } = req.body;
  if (!Array.isArray(nodes) || !task) return res.status(400).json({ error: 'nodes and task required' });

  const nodeMap = Object.fromEntries(nodes.map(n => [n.id, n]));
  const order = topoSort(nodes, edges || []);

  // Build agent content map from files
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const agentContentMap = {};

  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  for (const a of globalAgents) agentContentMap[a.name] = a.body || a.raw;

  for (const p of projects) {
    for (const a of p.agents) agentContentMap[a.name] = a.body || a.raw;
  }

  const results = {};
  let lastOutput = task;
  const runId = genId();
  const startedAt = new Date().toISOString();
  const runLogs = [];
  let runStatus = 'completed';

  // SSE for streaming progress
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => {
    runLogs.push(data);
    res.write(`data: ${JSON.stringify(data)}\n\n`);
  };

  try {
    for (const nodeId of order) {
      const node = nodeMap[nodeId];
      if (!node) continue;

      // Skip start/task-input nodes — store task as their output for downstream nodes
      if (node.data?.isStart) {
        results[nodeId] = task;
        send({ type: 'done', nodeId, label: node.data?.label || nodeId, output: task, skipped: true });
        continue;
      }

      const agentName = node.data?.agentName;
      const baseInstructions = agentName ? (agentContentMap[agentName] || '') : '';
      const nodeInstructions = node.data?.instructions || '';
      const nodeLabel = node.data?.label || agentName || nodeId;

      send({ type: 'start', nodeId, label: nodeLabel });

      // Build context from upstream node outputs
      const incomingEdges = (edges || []).filter(e => e.target === nodeId);
      let context = '';
      if (incomingEdges.length > 0) {
        context = incomingEdges.map(e => {
          const prevLabel = nodeMap[e.source]?.data?.label || e.source;
          return `## Output from ${prevLabel}:\n${results[e.source] || ''}`;
        }).join('\n\n');
      } else {
        context = `## Task:\n${task}`;
      }

      // Build prompt with clear structure: role → task → context → output directive
      let prompt = '';
      if (baseInstructions) {
        prompt += baseInstructions + '\n\n';
      }
      if (nodeInstructions) {
        prompt += `## Your Specific Task for This Step:\n${nodeInstructions}\n\n`;
      }
      prompt += `---\n\n${context}\n\n`;
      prompt += `---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary, evaluations, or descriptions of what you would do. Output only the finished work product itself.`;

      try {
        const output = await runClaudeSync(prompt);
        results[nodeId] = output;
        lastOutput = output;
        send({ type: 'done', nodeId, label: nodeLabel, output });
      } catch (err) {
        runStatus = 'failed';
        send({ type: 'error', nodeId, label: nodeLabel, error: err.message });
        break;
      }
    }
    send({ type: 'complete', finalOutput: lastOutput });
  } catch (err) {
    runStatus = 'failed';
    send({ type: 'error', nodeId: null, label: null, error: err.message });
  }

  // Persist run session to history
  const completedAt = new Date().toISOString();
  const duration = new Date(completedAt) - new Date(startedAt);
  const runSession = {
    id: runId,
    orchestrationName: req.body.orchestrationName || 'Untitled',
    orchestrationId: req.body.orchestrationId || null,
    task,
    status: runStatus,
    nodeCount: nodes.length,
    nodes: nodes.map(n => ({ id: n.id, label: n.data?.label, agentName: n.data?.agentName, isStart: n.data?.isStart, isCustom: n.data?.isCustom })),
    edges: (edges || []).map(e => ({ source: e.source, target: e.target })),
    logs: runLogs,
    nodeOutputs: results,
    finalOutput: lastOutput,
    startedAt,
    completedAt,
    duration,
  };
  try {
    const history = loadRunHistory();
    history.unshift(runSession);
    saveRunHistory(history);
  } catch {}

  res.end();
});

// Agent Playground — test any agent with a prompt (SSE streaming)
app.post('/api/playground/run', (req, res) => {
  const { agentName, prompt: userPrompt, customInstructions, timeoutMs } = req.body;
  if (!userPrompt) return res.status(400).json({ error: 'Prompt is required' });

  res.setTimeout(0);
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => res.write(`data: ${JSON.stringify(data)}\n\n`);

  // Load agent instructions
  let instructions = '';
  if (agentName) {
    const agentContentMap = {};
    const globalAgentsDir = path.join(CLAUDE_DIR, 'agents');
    if (fs.existsSync(globalAgentsDir)) {
      for (const file of fs.readdirSync(globalAgentsDir).filter(f => f.endsWith('.md'))) {
        const content = fs.readFileSync(path.join(globalAgentsDir, file), 'utf-8');
        const nameMatch = content.match(/^name:\s*(.+)$/m);
        const key = nameMatch ? nameMatch[1].trim() : file.replace('.md', '');
        agentContentMap[key] = content;
        agentContentMap[file.replace('.md', '')] = content;
      }
    }
    // Also check project agents
    const config = loadConfig();
    const projects = discoverProjects(config.projectDirs);
    for (const p of projects) {
      for (const a of (p.agents || [])) {
        agentContentMap[a.name] = a.body || a.raw;
        agentContentMap[a.filename] = a.body || a.raw;
      }
    }
    instructions = agentContentMap[agentName] || '';

    // Agent not found — warn the user
    if (!instructions) {
      send({ type: 'error', error: `Agent "${agentName}" not found in global or project agents` });
      res.end();
      return;
    }
  }

  if (customInstructions) {
    instructions = customInstructions;
  }

  let fullPrompt = '';
  if (instructions) {
    fullPrompt = `${instructions}\n\n---\n\n## Task:\n${userPrompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
  } else {
    fullPrompt = userPrompt;
  }

  const timeout = Math.min(timeoutMs ?? 120000, 600000); // max 10 min, ?? avoids 0 becoming falsy
  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;
  const proc = spawn(claudePath, ['-p'], { env: childEnv });
  let fullOutput = '';
  let killed = false;
  let ended = false; // Guard against double res.end()

  const finish = () => {
    if (ended) return;
    ended = true;
    try { res.end(); } catch {}
  };

  const timer = setTimeout(() => {
    killed = true;
    proc.kill('SIGTERM');
    setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
  }, timeout);

  send({ type: 'start', agent: agentName || 'custom' });

  proc.stdout.on('data', (data) => {
    if (ended) return;
    const chunk = data.toString();
    fullOutput += chunk;
    try { send({ type: 'chunk', content: chunk }); } catch {}
  });

  proc.stderr.on('data', () => {
    // stderr is informational — don't treat as fatal
  });

  proc.on('close', (code) => {
    clearTimeout(timer);
    if (ended) return;
    if (killed) {
      send({ type: 'error', error: `Timed out after ${timeout / 1000}s` });
    } else if (code !== 0 && !fullOutput.trim()) {
      send({ type: 'error', error: `Process exited with code ${code}` });
    } else {
      send({ type: 'done', output: fullOutput.trim() });
    }
    finish();
  });

  proc.on('error', (err) => {
    clearTimeout(timer);
    if (ended) return;
    send({ type: 'error', error: err.message });
    finish();
  });

  proc.stdin.write(fullPrompt, 'utf8');
  proc.stdin.end();

  // Handle client disconnect — kill the process
  req.on('close', () => {
    clearTimeout(timer);
    ended = true;
    if (!proc.killed) {
      proc.kill('SIGTERM');
      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 3000);
    }
  });
});

